using System;using System.IO;using System.Diagnostics;using System.Linq;using Newtonsoft.Json;using PlaytimeRclone;
class MetadataCloudProbe{static int Main(string[] a){try{var watch=Stopwatch.StartNew();var seeded=a.Length>5?MetadataCache.Seed(a[5],a[3]):0;var reports=0;var transport=new RcloneTransport(a[0],a[1],a[2],"playnite-link-v1",progress:p=>{reports++;if(reports%5==0)Console.WriteLine(p.Cached+" history records cached after "+watch.Elapsed.TotalSeconds.ToString("0.0")+"s");});transport.PullMetadata(a[3]);var first=watch.Elapsed.TotalSeconds;var count=MetadataCache.Count(a[3]);MetadataCache.Validate(a[3]);watch.Restart();transport.PullMetadata(a[3]);File.WriteAllText(a[4],JsonConvert.SerializeObject(new{passed=true,seededRecords=seeded,cachedRecords=count,firstSeconds=first,warmSeconds=watch.Elapsed.TotalSeconds,readonlyCloud=true},Formatting.Indented));Console.WriteLine(File.ReadAllText(a[4]));return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}}
